<script setup>
import { computed, ref } from 'vue'
import { workOrderStore as store, displayTime, timeFacts, statusTone, ACTION_LABELS, TERMINAL } from '../../data/workOrder.js'
import ActionForm from './ActionForm.vue'
import PhotoGallery from './PhotoGallery.vue'
const props = defineProps({ orderId: { type: String, required: true }, mobile: Boolean })
const emit = defineEmits(['close', 'edit'])
const order = computed(() => store.getOrder(props.orderId)), tab = ref('problem'), action = ref('')
const facts = computed(() => order.value ? timeFacts(order.value, store.now()) : {})
const terminal = computed(() => order.value && TERMINAL.includes(order.value.status))
const stageDeadline = computed(() => order.value?.status === '待验收' || (terminal.value && facts.value.submission) ? facts.value.submission?.acceptanceDeadline : facts.value.assignment?.deadline)
const actions = computed(() => store.actions(order.value))
function open(value) { if (value === 'edit') emit('edit', order.value); else action.value = value }
const snapshot = value => value ? (value.status || '') + (value.handlerId ? ' · ' + store.getName(value.handlerId) : '') + (value.acceptance ? ' · 验收 ' + (value.acceptance.name || store.acceptanceLabel(value.acceptance)) : '') + (value.deadline ? ' · 截止 ' + displayTime(value.deadline) : '') : ''
</script>
<template>
  <section v-if="order" class="detail">
    <header><div><span class="code">{{ order.code }}</span><h2>{{ order.title }}</h2></div><el-tag :type="statusTone(order.status)">{{ order.status }}</el-tag></header>
    <div class="tags"><el-tag effect="plain">{{ order.priority }}</el-tag><el-tag type="info">{{ order.categoryName }}</el-tag><el-tag v-if="order.seeded" type="info" effect="plain">内置演示样例</el-tag></div>
    <el-alert v-if="order.historyScopeAt" :title="'历史参与记录：仅可追溯至 ' + displayTime(order.historyScopeAt) + '，后续过程及附件不在当前账号授权范围。'" type="info" :closable="false" />
    <el-alert v-if="!order.historyScopeAt && TERMINAL.includes(order.status)" :title="order.status + ' · ' + displayTime(order.endedAt) + ' · ' + order.endReason + '，业务记录只读。'" type="info" :closable="false" />
    <el-alert v-if="!order.historyScopeAt && order.dispatchError && order.status === '待派发'" :title="'上次派发未完成：' + order.dispatchError" type="warning" :closable="false" />
    <el-alert v-if="!order.historyScopeAt && !TERMINAL.includes(order.status) && !store.acceptanceMembers(order, order.status === '待验收' ? facts.submission?.actor.id : order.handlerId).length" title="验收对象需调整：当前无有效候选，计时继续，发起人或管理人员可修改。" type="warning" :closable="false" />
    <div v-if="!order.historyScopeAt" class="responsibility">
      <div><small>当前主处理人／组织</small><strong>{{ store.getName(order.handlerId) }}</strong><span>{{ order.handlerOrganizationId ? store.orgName(order.handlerOrganizationId) : '无当前承接' }}</span></div>
      <div><small>当前验收对象</small><strong>{{ store.acceptanceLabel(order.acceptance) }}</strong><span>{{ order.acceptance.type === 'role' ? '共享事项，一人完成即结束' : '本单指定账号' }}</span></div>
      <div><small>{{ terminal ? '历史处理截止' : '当前处理截止' }}</small><strong>{{ displayTime(order.processingDeadline) }}</strong><span v-if="terminal">终态停止当前计时，历史及时性保留</span><span v-else-if="order.status === '待验收'">本次提交：{{ facts.submissionLate ? '逾期' : '按时' }}；提交后处理耗时停止累计</span><span v-else>{{ facts.processingLate ? '处理已超时' : order.processingDeadline ? '按本单截止执行' : '首次有效派发时确定' }}</span></div>
      <div><small>{{ terminal ? '最后阶段期限（历史）' : '本阶段期限' }}</small><strong>{{ displayTime(stageDeadline) }}</strong><span>{{ terminal ? '已结束，完整事实见流转和验收记录' : order.status === '待验收' ? (facts.acceptanceLate ? '验收已超时' : '本次验收期限') : order.status === '待接单' ? (facts.receivingLate ? '接单已超时' : '本次接单期限') : facts.assignment ? '本次派发的接单截止（历史）' : '尚无当前接单事项' }}</span></div>
    </div>
    <div v-if="actions.length" class="action-bar"><el-button v-for="value in actions" :key="value" :type="['receive','submit','review'].includes(value) ? 'primary' : value === 'terminate' ? 'danger' : 'default'" :plain="!['receive','submit','review'].includes(value)" @click="open(value)">{{ ACTION_LABELS[value] }}</el-button></div>
    <el-tabs v-model="tab">
      <el-tab-pane label="问题与来源" name="problem"><dl><dt>问题描述（首派后固化）</dt><dd class="pre">{{ order.description }}</dd><dt>所在位置</dt><dd>{{ order.spaceLabel }}<br>{{ order.location }}</dd><dt>关联设备／专业</dt><dd>{{ order.assetName || '未关联设备' }} · {{ order.profession || '待补专业' }}</dd><dt>来源</dt><dd>{{ order.source }}{{ order.sourceId ? ' · ' + order.sourceId : '' }}<p v-if="order.sourceId" class="hint">一对一来源占位，未实现自动转单或隐患销号。</p></dd><dt>发起人／时间</dt><dd>{{ order.initiator.name }} · {{ order.initiator.organizationName }} · {{ displayTime(order.createdAt) }}</dd></dl><PhotoGallery :order="order" :ids="order.originalPhotoIds" /><h3>问题补充</h3><el-empty v-if="!order.supplements.length" description="暂无补充说明" :image-size="55" /><article v-for="row in order.supplements" :key="row.id"><small>{{ row.actor.name }} · {{ displayTime(row.at) }}</small><p class="pre">{{ row.text }}</p><PhotoGallery :order="order" :ids="row.photoIds" /></article></el-tab-pane>
      <el-tab-pane label="处理过程" name="processing"><p v-if="!order.historyScopeAt" class="hint">当前协办：{{ order.collaboratorIds.map(id => store.getName(id)).join('、') || '无' }}</p><h3>过程反馈</h3><el-empty v-if="!order.feedbacks.length" description="暂无处理反馈" :image-size="55" /><article v-for="row in order.feedbacks" :key="row.id"><small>{{ row.actor.name }} · {{ row.actor.organizationName }} · {{ row.collaborator ? '协办' : '主处理人' }} · {{ displayTime(row.at) }}</small><p class="pre">{{ row.text }}</p><PhotoGallery :order="order" :ids="row.photoIds" /></article><h3>历次处理提交</h3><article v-for="row in order.submissions" :key="row.id"><strong>{{ row.id }} · {{ row.late ? '逾期提交' : '按时提交' }}</strong><p class="pre">{{ row.text }}</p><small>{{ row.actor.name }} · 提交 {{ displayTime(row.at) }}<br>提交时处理截止：{{ displayTime(row.processingDeadline) }}<br>本轮验收截止：{{ displayTime(row.acceptanceDeadline) }} · {{ row.outcome || '待验收' }}</small><PhotoGallery :order="order" :ids="row.photoIds" /></article></el-tab-pane>
      <el-tab-pane label="验收记录" name="reviews"><el-empty v-if="!order.reviews.length" description="暂无已完成验收记录" :image-size="55" /><article v-for="row in order.reviews" :key="row.id"><el-tag :type="row.conclusion === '通过' ? 'success' : 'warning'">{{ row.conclusion }}</el-tag><p class="pre">{{ row.text || '无附加说明' }}</p><small>对应提交：{{ row.submissionId }}<br>当时对象：{{ row.acceptance.name || row.acceptance.targetId }}<br>实际验收：{{ row.actor.name }} · {{ row.actor.organizationName }} · {{ displayTime(row.at) }}<br>验收截止：{{ displayTime(row.deadline) }} · {{ row.late ? '验收逾期' : '验收按时' }}</small><PhotoGallery :order="order" :ids="row.photoIds" /></article></el-tab-pane>
      <el-tab-pane label="流转历史" name="history"><h3>派发与交接</h3><article v-for="row in order.assignments" :key="row.id"><strong>{{ row.mode }} → {{ row.target.name }} · {{ row.target.organizationName }}</strong><p>{{ displayTime(row.at) }} · 接单截止 {{ displayTime(row.deadline) }}</p><p class="pre">{{ row.reason }}</p><small>实际接单：{{ displayTime(row.receivedAt) }} · {{ row.outcome || '待接单' }}{{ row.late === true ? '（本次逾期）' : '' }}<br v-if="row.rule"><template v-if="row.rule">命中：{{ row.rule.name }} V{{ row.rule.version }} · 顺序 {{ row.rule.sequence }}</template></small></article><h3>完整操作日志</h3><el-timeline><el-timeline-item v-for="row in order.logs.slice().reverse()" :key="row.id" :timestamp="displayTime(row.at)"><strong>{{ row.action }}</strong> · {{ row.actor.name }} · {{ row.actor.organizationName }}<p class="hint">{{ snapshot(row.before) }} → {{ snapshot(row.after) }}</p><p class="pre">{{ row.detail }}</p><small v-if="row.recordId">业务记录：{{ row.recordId }}</small></el-timeline-item></el-timeline></el-tab-pane>
      <el-tab-pane v-if="!order.historyScopeAt" label="配置与时限" name="config"><dl><dt>采用类别</dt><dd>{{ order.categorySnapshot.name }} V{{ order.categorySnapshot.version }} · {{ order.categorySnapshot.allowSelf ? '允许自验' : '禁止本次结果提交人自验' }}</dd><dt>本单验收取值</dt><dd>{{ order.acceptanceOrigin === 'manual' ? '人工明确指定，配置变化不覆盖' : '类别默认解析' }}</dd><dt>采用时长（演示自然分钟）</dt><dd>接单 {{ order.durations.receiving }} / 处理 {{ order.durations.processing }} / 验收 {{ order.durations.acceptance }}</dd><dt>首次派发</dt><dd>{{ displayTime(order.firstDispatchedAt) }}</dd><dt>原始处理截止</dt><dd>{{ displayTime(order.originalDeadline) }}</dd><dt>当前处理截止</dt><dd>{{ displayTime(order.processingDeadline) }}</dd><dt>最终处理及时性</dt><dd>{{ order.finalSubmissionId ? (order.submissions.find(row => row.id === order.finalSubmissionId)?.late ? '逾期' : '按时') : '尚无通过验收所对应的提交' }}</dd></dl><article v-for="row in order.deadlineChanges" :key="row.id"><p>{{ displayTime(row.before) }} → {{ displayTime(row.after) }}</p><p>{{ row.reason }}</p><small>{{ row.actor.name }} · {{ displayTime(row.at) }} · 调整时原期限{{ row.wasLate ? '已超时' : '未超时' }}</small></article><template v-if="order.lastRuleAttempt"><h3>最近规则尝试</h3><p>{{ order.lastRuleAttempt.rule?.name || '无匹配规则' }} · {{ displayTime(order.lastRuleAttempt.at) }}</p><p>{{ order.lastRuleAttempt.error || '派发成功' }}</p></template></el-tab-pane>
    </el-tabs>
    <el-dialog :model-value="Boolean(action)" :title="ACTION_LABELS[action]" width="min(660px,96vw)" class="ez-dialog" append-to-body destroy-on-close :close-on-click-modal="false" @update:model-value="value => { if (!value) action = '' }"><ActionForm v-if="action" :key="action" :order="order" :action="action" @done="action = ''" @cancel="action = ''" /></el-dialog>
  </section>
  <el-empty v-else description="当前演示账号无权查看此工单，或该单已不可访问"><el-button @click="emit('close')">返回列表</el-button></el-empty>
</template>
<style scoped>
.detail{display:grid;gap:16px;color:var(--ez-text);font-size:14px;line-height:1.8}header{display:flex;align-items:flex-start;justify-content:space-between;gap:12px}h2{font-size:20px;line-height:1.5;margin-top:6px}.code,small,.hint{font-size:12px;color:var(--ez-text-secondary)}.tags,.action-bar{display:flex;gap:8px;flex-wrap:wrap}.action-bar .el-button{margin:0}.responsibility{display:grid;grid-template-columns:1fr 1fr;gap:12px;background:var(--ez-fill-light);padding:16px;border-radius:12px}.responsibility div{display:flex;flex-direction:column;overflow-wrap:anywhere}.responsibility strong{font-size:14px}.responsibility span{font-size:12px;color:var(--ez-text-secondary)}dt{font-size:12px;color:var(--ez-text-secondary);margin-top:14px}dd{margin:4px 0;overflow-wrap:anywhere}article{border:1px solid var(--ez-border);border-radius:10px;padding:14px;margin:12px 0}h3{font-size:16px;margin:18px 0 10px}.pre{white-space:pre-wrap;overflow-wrap:anywhere;margin:6px 0}:deep(.el-tabs__content){overflow:visible}:deep(.el-tabs__nav-wrap){max-width:100%}@media(max-width:600px){.responsibility{grid-template-columns:1fr}.action-bar{position:sticky;top:0;background:var(--ez-card-bg);padding:10px 0;z-index:2}.action-bar .el-button{font-size:12px;padding:8px 10px}h2{font-size:18px}}
</style>
